package com.smartseating.ui;

import com.smartseating.dao.UserDAO;
import com.smartseating.model.User;
import com.smartseating.service.PrintService;
import com.smartseating.util.*;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;
import java.util.List;

public class UserFrame extends AppFrame {
    private final UserDAO dao=new UserDAO();private final JTextField username=new JTextField(),password=new JTextField(),fullName=new JTextField();private final JComboBox<String> role=new JComboBox<>(new String[]{"ADMIN","TEACHER"}),status=new JComboBox<>(new String[]{"ACTIVE","INACTIVE"});private final JTable table=new JTable();private User selected;
    public UserFrame(User user){super("User Management",user);UI.frame(this,960,600);build();refresh();}
    private void build(){content.add(title("System User Management"),BorderLayout.NORTH);JPanel form=UI.formPanel();UI.addField(form,0,"Username",username);UI.addField(form,1,"Password",password);UI.addField(form,2,"Full Name",fullName);UI.addField(form,3,"Role",role);UI.addField(form,4,"Status",status);JPanel a=new JPanel(new GridLayout(2,3,7,7));a.setOpaque(false);JButton add=button("ADD",UI.TEAL),update=button("UPDATE",UI.BLUE),del=button("DELETE",new Color(190,66,66)),clear=button("CLEAR",UI.MUTED),print=button("PRINT",UI.ORANGE);for(JButton b:new JButton[]{add,update,del,clear,print})a.add(b);GridBagConstraints g=new GridBagConstraints();g.gridx=0;g.gridy=5;g.gridwidth=2;g.fill=GridBagConstraints.HORIZONTAL;g.insets=new Insets(14,6,6,6);form.add(a,g);content.add(white(form),BorderLayout.WEST);UI.tableStyle(table);content.add(white(UI.scroll(table)),BorderLayout.CENTER);add.addActionListener(e->save());update.addActionListener(e->update());del.addActionListener(e->delete());clear.addActionListener(e->clear());print.addActionListener(e->PrintService.print("System User List",text()));table.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&table.getSelectedRow()>=0)load();});}
    private User read(){User u=new User();u.setUsername(Validation.text(username.getText(),"Username"));u.setPassword(Validation.text(password.getText(),"Password"));u.setFullName(Validation.text(fullName.getText(),"Full name"));u.setRole((String)role.getSelectedItem());u.setStatus((String)status.getSelectedItem());return u;}
    private void save(){try{dao.save(read());clear();refresh();}catch(Exception ex){error(ex);}}private void update(){try{if(selected==null)throw new IllegalArgumentException("Select a user first.");User u=read();u.setId(selected.getId());dao.update(u);clear();refresh();}catch(Exception ex){error(ex);}}private void delete(){try{if(selected==null)throw new IllegalArgumentException("Select a user first.");if(selected.getUsername().equals(currentUser.getUsername()))throw new IllegalArgumentException("You cannot delete the account currently in use.");if(confirm("Delete selected user?")){dao.delete(selected.getId());clear();refresh();}}catch(Exception ex){error(ex);}}private void load(){int r=table.getSelectedRow();selected=new User((int)table.getValueAt(r,0),String.valueOf(table.getValueAt(r,1)),String.valueOf(table.getValueAt(r,3)),String.valueOf(table.getValueAt(r,2)));username.setText(selected.getUsername());fullName.setText(selected.getFullName());password.setText("");role.setSelectedItem(selected.getRole());status.setSelectedItem(selected.getStatus());}private void clear(){selected=null;username.setText("");password.setText("");fullName.setText("");role.setSelectedIndex(0);status.setSelectedIndex(0);table.clearSelection();}private void refresh(){try{DefaultTableModel m=new DefaultTableModel(new Object[]{"ID","Username","Full Name","Role","Status"},0);for(User u:dao.findAll())m.addRow(new Object[]{u.getId(),u.getUsername(),u.getFullName(),u.getRole(),u.getStatus()});table.setModel(m);UI.tableStyle(table);}catch(Exception ex){error(ex);}}private String text(){StringBuilder b=new StringBuilder("SYSTEM USER LIST\n\n");for(int i=0;i<table.getRowCount();i++)b.append(table.getValueAt(i,1)).append(" | ").append(table.getValueAt(i,2)).append(" | ").append(table.getValueAt(i,3)).append(" | ").append(table.getValueAt(i,4)).append("\n");return b.toString();}
}
